<?php require_once '../includes/functions.php';require_admin();if(isset($_GET['toggle'])){$id=(int)$_GET['toggle'];if($id!==user()['id'])$pdo->prepare("UPDATE users SET status=IF(status='active','blocked','active') WHERE id=?")->execute([$id]);redirect('admin/users.php');}$rows=$pdo->query('SELECT id,name,email,role,status,created_at FROM users ORDER BY created_at DESC')->fetchAll();$page_title='Manage Users';require '../includes/header.php';?><section class="section"><h1>Manage Users</h1><div class="table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Status</th><th>Joined</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $u):?><tr><td><?=e($u['name'])?></td><td><?=e($u['email'])?></td><td><?=e($u['role'])?></td><td><?=e($u['status'])?></td><td><?=e($u['created_at'])?></td><td><?php if($u['id']!==user()['id']):?><a class="btn btn-outline btn-small" href="?toggle=<?=$u['id']?>"><?=$u['status']==='active'?'Block':'Activate'?></a><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section><?php require '../includes/footer.php';?>
